// 03 ばねと棒
const spring = (x: number, y0: number, y1: number, col: string): E[] => {
  const out: E[] = []; const n = 8; const dy = (y1 - y0) / n;
  for (let i = 0; i < n; i++) out.push(ln(x + (i % 2 ? 7 : -7), y0 + i * dy, x + ((i + 1) % 2 ? 7 : -7), y0 + (i + 1) * dy, col, false, 1.8));
  return out;
};
